export const TABLA_ASIGNACIONES = new Table({
  name: process.env.TABLA_ASIGNACIONES,
  documentClient: db,
  partitionKey: { name: 'REPARACION_ID', type: 'number' },
  sortKey: { name: 'MECANICO_ID', type: 'number' },
  indexes: {
    PorMecanico: {
