import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_REPARACION } from '../../models/taller-reparacion.model.mjs';
import { MODELO_MECANICO, MODELO_ASIGNACION } from '../../models/mecanico-asignacion.model.mjs';

export async function buscarReparacionRepository(reparacionId) {
  const { Item } = await MODELO_REPARACION.build(EntityRepository).get(
    { reparacionId },
    { consistent: true }
  );
  return Item;
}

export async function buscarMecanicoRepository(mecanicoId) {
  const { Item } = await MODELO_MECANICO.build(EntityRepository).get(
    { mecanicoId },
    { consistent: true }
  );
  return Item;
}

export async function asignarMecanicoRepository(reparacionId, mecanicoId, rol) {
  const asignacion = { reparacionId, mecanicoId, rol };
  await MODELO_ASIGNACION.build(EntityRepository).put(
    asignacion,
    { condition: { attr: 'reparacionId', exists: false } }
  );
  return asignacion;
}

import { buscarReparacionRepository, buscarMecanicoRepository, asignarMecanicoRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarMecanicoService(reparacionId, mecanicoId, rol) {
  const reparacion = await buscarReparacionRepository(reparacionId);
  const mecanico = await buscarMecanicoRepository(mecanicoId);
  if (!reparacion || !mecanico) {
    throw new ReferenciaInexistenteError('No existe la reparacion o el mecanico');
  }
  return asignarMecanicoRepository(reparacionId, mecanicoId, rol);
}

import { asignarMecanicoService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const reparacionId = Number(event.pathParameters.reparacionId);
  const { mecanicoId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarMecanicoService(reparacionId, mecanicoId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El mecanico ya está asignado a esa reparacion' }) };
    }
    throw error;
  }
}

